using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using RoadGunner;using RoadGunner.Editor;
public static class ConceptBaseline { public static string Main(){var l=RoadGunnerLevelAuthoring.Current;var s=l.session;string root="/Users/arthuri/Documents/Codex/2026-10-09/macbook-app-store/work/concept-overhaul-2026-10-16/";var lines=new System.Collections.Generic.List<string>();lines.Add("Scene="+l.gameObject.scene.path+" dirty="+l.gameObject.scene.isDirty);lines.Add("Bounds="+l.gameplayBounds+" ground="+l.ground.sharedMesh.bounds+" spawn="+l.playerSpawn.position+" scale="+l.appliedFootprintScale);foreach(var c in new UnityEngine.Component[]{s.vehicle,s.vehicle.GetComponent<Rigidbody>(),s.vehicle.GetComponent<BoxCollider>(),s.turret,s.vehicle.GetComponent<HarpoonCollector>(),s.health,s.spawns,s.pickups,s.follow,UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>()})lines.Add(c.GetType().Name+" "+EditorJsonUtility.ToJson(c));foreach(var c in s.vehicle.wheels)lines.Add("Wheel "+EditorJsonUtility.ToJson(c)+" transform="+c.transform.localPosition+":"+c.transform.localEulerAngles);foreach(var p in s.spawns.authoredRaiders)lines.Add("Raider "+p.name+" p="+p.transform.position+" r="+p.transform.rotation+" scale="+p.transform.lossyScale+" tuning="+AssetDatabase.GetAssetPath(p.tuning));foreach(var c in new[]{s.turret.yaw,s.turret.pitch,s.turret.muzzle,s.vehicle.GetComponent<HarpoonCollector>().pivot,s.vehicle.GetComponent<HarpoonCollector>().spawnPoint,s.vehicle.GetComponent<HarpoonCollector>().collectionPoint})lines.Add("Pivot "+c.name+" local="+c.localPosition+" localrot="+c.localRotation+" scale="+c.localScale);File.WriteAllLines(root+"BaselineComponents.txt",lines);return string.Join("\n",lines.Take(2));}}
